<?php foreach($paypalMaps as $pm): ?><form method="post"><?= csrf().hidden('action','paypal-sync').hidden('mapping',$pm['id']).hidden('request_key',bin2hex(random_bytes(16))) ?><h3><?= e($pm['account_name']) ?></h3><label>Von<input class="form-control" type="date" name="date_from" value="<?= (new \DateTimeImmutable(\Kulturhus\Verein\Finance::today(),new \DateTimeZone('Europe/Berlin')))->modify('-14 days')->format('Y-m-d') ?>" required></label><label>Bis<input class="form-control" type="date" name="date_to" value="<?= \Kulturhus\Verein\Finance::today() ?>" required></label><p>Höchstens 31 Tage je vollständigem Abruf. Ein API-Kontostand ersetzt keine gespeicherten Buchungen.</p><button class="btn btn-solid theme-primary">PayPal-Umsätze und Kontostand abrufen</button></form><?php $bs=$db->prepare('SELECT observed_at,payload FROM paypal_balance_snapshots WHERE club_id=? AND mapping_id=?');$bs->execute([$pm['club_id'],$pm['id']]);if($balance=$bs->fetch()): ?><p>Letzter API-Kontostand: <?= e($balance['observed_at']) ?></p><?php foreach(json_decode($balance['payload'],true)['balances'] as $b): ?><p><?= e(($b['total_balance']['value']??'').' '.($b['total_balance']['currency_code']??'')) ?> · verfügbar <?= e($b['available_balance']['value']??'') ?> · einbehalten <?= e($b['withheld_balance']['value']??'') ?></p><?php endforeach;endif;endforeach ?>
<?php else: ?><p>PayPal-API noch nicht eingerichtet.</p><?php endif ?></details>
<?php if($remote&&!$mapping): ?><form method="post"><?= csrf().hidden('action','enable-map').hidden('bank_environment','PRODUCTION').hidden('bank_uid',$uid) ?><label>Zu welchem Vereinskonto gehört dieses Bankkonto?<select class="form-control" name="account_id" required><option value="">Vereinskonto auswählen</option><?php foreach($finance->paymentAccounts() as $account)if($account['kind']==='offline'): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endif ?></select></label><p>Der Anfangsbestand dieses Kontos muss zum ersten übernommenen Buchungsdatum passen.</p><button class="btn btn-solid theme-primary">Bankkonto zuordnen</button></form>
<?php elseif($mapping): ?><form method="post"><?= csrf().hidden('action','enable-import').hidden('bank_environment','PRODUCTION').hidden('bank_uid',$uid).hidden('mapping',$mapping['id']).hidden('request_key',bin2hex(random_bytes(16))) ?><h3><?= e($mapping['account_name']) ?></h3><div class="form-grid"><label>Umsätze ab<input class="form-control" type="date" name="date_from" required max="<?= \Kulturhus\Verein\Finance::today() ?>" value="<?= date('Y-m-d',strtotime('-90 days')) ?>"></label><label>Bis einschließlich<input class="form-control" type="date" name="date_to" required max="<?= \Kulturhus\Verein\Finance::today() ?>" value="<?= \Kulturhus\Verein\Finance::today() ?>"></label></div><button class="btn btn-solid theme-primary">Umsätze abrufen und speichern</button></form>
<?php else: ?><p>Oben ein freigegebenes Bankkonto öffnen. Danach das zugehörige Vereinskonto einmal auswählen.</p><?php endif ?>
